def _build_server_call_context(request: Request) -> ServerCallContext:
    """Build a ``ServerCallContext`` from a Sanic request.

    When bearer auth is configured and the request passed validation, the user
    is an ``A2AAuthenticatedUser``. Otherwise, the user is ``UnauthenticatedUser``.
    Header state and extension negotiation match the SDK call-context builder,
    including the legacy ``X-A2A-Extensions`` name that 0.3 clients still send
    (``V03ServerCallContextBuilder``).
    """
    headers = {
        key: value
        for key, value in request.headers.items()
        if key.lower() != "authorization"
    }
    extension_values = [
        *request.headers.getall(HTTP_EXTENSION_HEADER, []),
        *request.headers.getall(LEGACY_HTTP_EXTENSION_HEADER, []),
    ]
    auth_payload = getattr(request.ctx, "a2a_auth_payload", None)
    user: A2AUser
    state: dict[str, Any]
    if auth_payload is not None:
        user = A2AAuthenticatedUser(auth_payload)
        state = {"auth": auth_payload, "headers": headers}
    else:
        user = UnauthenticatedUser()
        state = {"headers": headers}
    return ServerCallContext(
        user=user,
        state=state,
        requested_extensions=get_requested_extensions(extension_values),
    )


def _unauthorized_response() -> HTTPResponse:
    """Return HTTP 401 for missing or invalid orchestrator bearer credentials."""
    return sanic_json(
        A2A_UNAUTHORIZED_RESPONSE_BODY,
        status=401,
        headers=a2a_bearer_unauthorized_response_headers(),
    )


def _validate_a2a_bearer_auth(request: Request) -> HTTPResponse | None:
    """Validate bearer JWT when auth is configured on the A2A server.

    Returns an HTTP 401 response with ``WWW-Authenticate: Bearer`` when
    validation fails. When auth is not configured, or validation succeeds,
    returns ``None``.
    """
    validator: A2ABearerAuthValidator | None = getattr(
        request.app.ctx, "a2a_bearer_auth_validator", None
    )
    if validator is None:
        return None

    jwt_payload = validator.validate_authorization_header(
        request.headers.get("Authorization")
    )
    if jwt_payload is None:
        structlogger.debug(
            "a2a_server.sanic_app.auth_rejected",
            path=request.path,
        )
        return _unauthorized_response()

    request.ctx.a2a_auth_payload = jwt_payload
    return None


def _extract_request_id(body: Any) -> str | int | None:
    """Read a JSON-RPC ``id`` from a parsed request body, if present."""
    if isinstance(body, dict):
        raw_id = body.get("id")
        if isinstance(raw_id, str | int):
            return raw_id
    return None


def _payload_too_large_response(request: Request) -> HTTPResponse | None:
    """Return an error response when ``Content-Length`` exceeds the limit."""
    try:
        content_length = int(request.headers.get("content-length", "0"))
    except ValueError:
        return None
    if content_length and content_length > _MAX_CONTENT_LENGTH:
        return _jsonrpc_error_response(
            None, InvalidRequestError(message="Payload too large")
        )
    return None


def _parse_json_body(
    request: Request,
) -> tuple[HTTPResponse | None, Any, str | int | None]:
    """Parse the POST body as JSON.

    Returns ``(error_response, body, request_id)``. When ``error_response`` is
    set, ``body`` and ``request_id`` are not used.
    """
    try:
        body = request.json
    except Exception as exc:
        return (
            _jsonrpc_error_response(None, JSONParseError(message=str(exc))),
            None,
            None,
        )

    if body is None:
        return (
            _jsonrpc_error_response(
                None, JSONParseError(message="Empty or non-JSON body")
            ),
            None,
            None,
        )

    return None, body, _extract_request_id(body)


def _declared_protocol_version(context: ServerCallContext) -> str:
    """Return the requested ``Major.Minor`` version. A missing header is 0.3."""
    headers = context.state.get("headers", {})
    raw = headers.get(constants.VERSION_HEADER) or headers.get(
        constants.VERSION_HEADER.lower()
    )
    text = str(raw).strip() if raw else ""
    return text or constants.PROTOCOL_VERSION_0_3


def _major_minor_matches(actual: str, expected: str) -> bool:
    """Compare protocol versions on major and minor. Patch is ignored."""
    try:
        actual_version = Version(actual)
        expected_version = Version(expected)
    except InvalidVersion:
        return False
    return (actual_version.major, actual_version.minor) == (
        expected_version.major,
        expected_version.minor,
    )


def _ensure_protocol_version(context: ServerCallContext, expected: str) -> None:
    """Reject a request whose ``A2A-Version`` is not this method's version.

    The SDK decorator compares major only, so ``1.1`` would otherwise be
    handled as ``1.0`` and ``0.4`` as ``0.3``.
    """
    actual = _declared_protocol_version(context)
    if _major_minor_matches(actual, expected):
        return
    raise VersionNotSupportedError(
        message=(f"A2A version '{actual}' is not supported. Expected '{expected}'.")
    )


def _activated_extension_headers(context: ServerCallContext) -> dict[str, str]:
    """Echo extensions the server activated for this call.

    ``requested_extensions`` is what the client asked for. Per spec only
    extensions the server actually activated are echoed back, and a2a-sdk 1.x
    has no field for that on ``ServerCallContext``, so an executor or handler
    that activates an extension records its URI in
    ``state['activated_extensions']``. Rasa currently activates none, so the
    header is normally absent.
    """
    raw = context.state.get("activated_extensions") or set()
    exts = {str(item).strip() for item in raw if str(item).strip()}
    if exts:
        return {HTTP_EXTENSION_HEADER: ", ".join(sorted(exts))}
    return {}


def _jsonrpc_error_response(
    request_id: str | int | None,
    error: JSONRPCError | A2AError | Exception,
    *,
    http_status: int = 200,
) -> HTTPResponse:
    """Serialise a JSON-RPC error payload as a Sanic response."""
    payload = build_error_response(request_id, error)
    error_info = payload.get("error", {})
    log = (
        structlogger.error
        if error_info.get("code") == InternalError().code
        else structlogger.warning
    )
    log(
        "a2a_server.sanic_app.request_error",
        request_id=request_id,
        code=error_info.get("code"),
        message=error_info.get("message"),
        http_status=http_status,
    )
    return sanic_json(payload, status=http_status)


def _jsonrpc_result_response(
    payload: dict[str, Any],
    extra_headers: dict[str, str],
) -> HTTPResponse:
    """Serialise a JSON-RPC success payload as a Sanic response."""
    return sanic_json(payload, headers=extra_headers, status=200)


def _request_handler(request: Request) -> Any:
    """Return ``app.ctx.a2a_request_handler``, or legacy ``a2a_jsonrpc_handler``."""
    ctx = request.app.ctx
    handler = getattr(ctx, "a2a_request_handler", None)
    if handler is not None:
        return handler
    return getattr(ctx, "a2a_jsonrpc_handler", None)


def _success_payload(request_id: str | int | None, result: Any) -> dict[str, Any]:
    """Build a JSON-RPC success body. ``None`` is a null result, not a proto."""
    if result is None or isinstance(result, dict):
        body: Any = result
    else:
        body = MessageToDict(result, preserving_proto_field_name=False)
    return JSONRPC20Response(result=body, _id=request_id).data


@validate_version(constants.PROTOCOL_VERSION_1_0)
async def _dispatch_native(
    handler: Any,
    method: str,
    request_obj: Any,
    context: ServerCallContext,
    request_id: str | int | None,
) -> dict[str, Any] | None:
    """Dispatch one native 1.0 JSON-RPC method. Returns the result object."""
    if method == "SendMessage":
        task_or_message = await handler.on_message_send(request_obj, context)
        if isinstance(task_or_message, Task):
            return MessageToDict(SendMessageResponse(task=task_or_message))
        return MessageToDict(SendMessageResponse(message=task_or_message))
    if method == "CancelTask":
        task = await handler.on_cancel_task(request_obj, context)
        if task is None:
            raise TaskNotFoundError
        return MessageToDict(task, preserving_proto_field_name=False)
    if method == "GetTask":
        task = await handler.on_get_task(request_obj, context)
        if task is None:
            raise TaskNotFoundError
        return MessageToDict(task, preserving_proto_field_name=False)
    if method == "ListTasks":
        tasks_response = await handler.on_list_tasks(request_obj, context)
        return serialize_list_tasks_response(
            tasks_response, request_obj.include_artifacts
        )
    if method == "CreateTaskPushNotificationConfig":
        config = await handler.on_create_task_push_notification_config(
            request_obj, context
        )
        return MessageToDict(config, preserving_proto_field_name=False)
    if method == "GetTaskPushNotificationConfig":
        config = await handler.on_get_task_push_notification_config(
            request_obj, context
        )
        return MessageToDict(config, preserving_proto_field_name=False)
    if method == "ListTaskPushNotificationConfigs":
        configs = await handler.on_list_task_push_notification_configs(
            request_obj, context
        )
        return MessageToDict(configs, preserving_proto_field_name=False)
    if method == "DeleteTaskPushNotificationConfig":
        await handler.on_delete_task_push_notification_config(request_obj, context)
        return None
    if method == "GetExtendedAgentCard":
        card = await handler.on_get_extended_agent_card(request_obj, context)
        return MessageToDict(card, preserving_proto_field_name=False)
    raise UnsupportedOperationError(message=f"Method {method} is not supported.")


@validate_version(constants.PROTOCOL_VERSION_1_0)
async def _native_stream(
    handler: Any,
    method: str,
    request_obj: Any,
    context: ServerCallContext,
) -> AsyncGenerator[Any, None]:
    """Yield 1.0 stream events (``SendStreamingMessage`` / ``SubscribeToTask``)."""
    if method == "SendStreamingMessage":
        stream = handler.on_message_send_stream(request_obj, context)
    elif method == "SubscribeToTask":
        stream = handler.on_subscribe_to_task(request_obj, context)
    else:
        raise UnsupportedOperationError(message="Stream not supported")
    async for event in stream:
        yield event


@validate_version(constants.PROTOCOL_VERSION_0_3)
async def _dispatch_v03(
    adapter: RequestHandler03,
    request_obj: Any,
    context: ServerCallContext,
    request_id: str | int | None,
) -> Any:
    """Run one non-streaming v0.3 method and return a pydantic response model."""
    method = request_obj.method
    result: Any
    if method == "message/send":
        result = await adapter.on_message_send(request_obj, context)
        return types_v03.SendMessageResponse(
            root=types_v03.SendMessageSuccessResponse(id=request_id, result=result)
        )
    if method == "tasks/get":
        result = await adapter.on_get_task(request_obj, context)
        return types_v03.GetTaskResponse(
            root=types_v03.GetTaskSuccessResponse(id=request_id, result=result)
        )
    if method == "tasks/cancel":
        result = await adapter.on_cancel_task(request_obj, context)
        return types_v03.CancelTaskResponse(
            root=types_v03.CancelTaskSuccessResponse(id=request_id, result=result)
        )
    if method == "tasks/pushNotificationConfig/get":
        result = await adapter.on_get_task_push_notification_config(
            request_obj, context
        )
        return types_v03.GetTaskPushNotificationConfigResponse(
            root=types_v03.GetTaskPushNotificationConfigSuccessResponse(
                id=request_id, result=result
            )
        )
    if method == "tasks/pushNotificationConfig/set":
        result = await adapter.on_create_task_push_notification_config(
            request_obj, context
        )
        return types_v03.SetTaskPushNotificationConfigResponse(
            root=types_v03.SetTaskPushNotificationConfigSuccessResponse(
                id=request_id, result=result
            )
        )
    if method == "tasks/pushNotificationConfig/list":
        result = await adapter.on_list_task_push_notification_configs(
            request_obj, context
        )
        return types_v03.ListTaskPushNotificationConfigResponse(
            root=types_v03.ListTaskPushNotificationConfigSuccessResponse(
                id=request_id, result=result
            )
        )
    if method == "tasks/pushNotificationConfig/delete":
        await adapter.on_delete_task_push_notification_config(request_obj, context)
        return types_v03.DeleteTaskPushNotificationConfigResponse(
            root=types_v03.DeleteTaskPushNotificationConfigSuccessResponse(
                id=request_id, result=None
            )
        )
    if method == "agent/getAuthenticatedExtendedCard":
        result = await adapter.on_get_extended_agent_card(request_obj, context)
        return types_v03.GetAuthenticatedExtendedCardResponse(
            root=types_v03.GetAuthenticatedExtendedCardSuccessResponse(
                id=request_id, result=result
            )
        )
    raise UnsupportedOperationError(message=f"Method {method} is not supported.")


@validate_version(constants.PROTOCOL_VERSION_0_3)
async def _v03_stream(
    adapter: RequestHandler03,
    request_obj: Any,
    context: ServerCallContext,
) -> AsyncGenerator[Any, None]:
    """Yield v0.3 stream items (``message/stream`` / ``tasks/resubscribe``)."""
    method = request_obj.method
    if method == "message/stream":
        source = adapter.on_message_send_stream(request_obj, context)
    elif method == "tasks/resubscribe":
        source = adapter.on_subscribe_to_task(request_obj, context)
    else:
        raise UnsupportedOperationError(
            message=f"Unsupported streaming method {method}"
        )
    async for item in source:
        yield item


def _create_sse_response(
    async_gen: AsyncIterable[dict[str, Any] | str],
    context: ServerCallContext,
    request_id: str | int | None = None,
) -> ResponseStream:
    """Return a Sanic ``ResponseStream`` that encodes JSON-RPC events as SSE.

    Returning ``ResponseStream`` (instead of calling ``request.respond()`` and
    returning ``None``) lets Sanic finish the HTTP lifecycle correctly under
    ASGI: after the first chunk, ASGI clears ``request.stream.response``, so a
    ``None`` return triggers ``Invalid response type None``.
    """
    extra_headers = _activated_extension_headers(context)

    async def stream_sse(resp: ResponseStream) -> None:
        try:
            async for item in async_gen:
                if isinstance(item, str):
                    data = item
                else:
                    data = json.dumps(item)
                await resp.write(f"data: {data}\n\n")
        except Exception as exc:
            structlogger.exception("a2a_server.sanic_app.stream_sse.error")
            error: A2AError | InternalError = (
                exc
                if isinstance(exc, A2AError)
                else InternalError(message="Internal server error")
            )
            payload = build_error_response(request_id, error)
            try:
                await resp.write(f"data: {json.dumps(payload)}\n\n")
            except Exception:
                structlogger.exception(
                    "a2a_server.sanic_app.stream_sse.error_frame_failed"
                )

    return ResponseStream(
        stream_sse,
        content_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            **extra_headers,
        },
    )


async def _sse_from_events(
    request_id: str | int | None,
    stream: AsyncIterable[Any],
    context: ServerCallContext,
    *,
    compat: bool,
) -> HTTPResponse | ResponseStream:
    """Prime the stream so setup errors stay JSON-RPC, then continue as SSE.

    Awaiting the first event before opening SSE allows in-flight 409 conflicts
    and other setup failures to return a normal JSON-RPC response instead of an
    empty or broken event stream.
    """

    async def encoded() -> AsyncGenerator[dict[str, Any] | str, None]:
        async for event in stream:
            if compat:
                yield event.model_dump_json(by_alias=True, exclude_none=True)
            else:
                stream_response = proto_utils.to_stream_response(event)
                result = MessageToDict(
                    stream_response, preserving_proto_field_name=False
                )
                yield JSONRPC20Response(result=result, _id=request_id).data

    generator = encoded()
    try:
        first = await anext(generator)
    except StopAsyncIteration:
        return _create_sse_response(generator, context, request_id)
    except A2AMessageInFlightConflict as exc:
        return _jsonrpc_in_flight_conflict_response(request_id, exc)
    except A2AError as exc:
        return _jsonrpc_error_response(request_id, exc)

    async def with_first() -> AsyncGenerator[dict[str, Any] | str, None]:
        yield first
        async for item in generator:
            yield item

    return _create_sse_response(with_first(), context, request_id)


def _jsonrpc_in_flight_conflict_response(
    request_id: str | int | None,
    exc: A2AMessageInFlightConflict,
) -> HTTPResponse:
    """Return HTTP 409 for duplicate ``messageId`` while the first request runs."""
    structlogger.warning(
        "a2a_server.sanic_app.message_in_flight_conflict",
        request_id=request_id,
        context_id=exc.context_id,
        message_id=exc.message_id,
    )
    return _jsonrpc_error_response(
        request_id,
        InvalidParamsError(
            message=(
                f"message_id {exc.message_id!r} is already in flight "
                f"for context {exc.context_id!r}"
            )
        ),
        http_status=409,
    )


def agent_card_payload(card: "AgentCard") -> dict[str, Any]:
    """Serialize an ``AgentCard``, including hybrid ``url`` when 0.3 is declared."""
    return agent_card_to_dict(card)


def set_a2a_agent_card_ctx(app: "Sanic", card: "AgentCard") -> None:
    """Store the runtime card and its serialized payload on ``app.ctx``."""
    app.ctx.a2a_agent_card = card
    app.ctx.a2a_agent_card_payload = agent_card_payload(card)


def create_a2a_blueprint() -> Blueprint:
    """Return a Sanic ``Blueprint`` that serves the A2A protocol.

    The blueprint has no URL prefix so its routes sit at the server root (see
    module docstring). Handlers read ``app.ctx.a2a_request_handler`` (or legacy
    ``a2a_jsonrpc_handler``) and ``app.ctx.a2a_agent_card_payload`` at request
    time. Callers set the card payload when registering the blueprint and again
    at ``after_server_start`` when the runtime card is resolved.
    """
    bp = Blueprint("a2a", url_prefix="")

    def _agent_card_response(request: Request) -> HTTPResponse:
        """AgentCard JSON with cache and ETag headers (spec SHOULD).

        A public card may be cached by shared proxies. When bearer auth is
        configured the card is private so a shared cache cannot replay it
        without ``Authorization``.
        """
        payload = request.app.ctx.a2a_agent_card_payload
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        etag = hashlib.sha256(canonical.encode()).hexdigest()
        auth_configured = (
            getattr(request.app.ctx, "a2a_bearer_auth_validator", None) is not None
        )
        headers = {
            "Cache-Control": (
                "private, max-age=300" if auth_configured else "public, max-age=300"
            ),
            "ETag": f'"{etag}"',
        }
        if auth_configured:
            headers["Vary"] = "Authorization"
        return sanic_json(payload, status=200, headers=headers)

    def _serve_agent_card_if_authorized(request: Request) -> HTTPResponse:
        if auth_error := _validate_a2a_bearer_auth(request):
            return auth_error
        return _agent_card_response(request)

    # ------------------------------------------------------------------ #
    # JSON-RPC endpoint                                                    #
    # ------------------------------------------------------------------ #

    @bp.post(constants.DEFAULT_RPC_URL)
    async def handle_jsonrpc(request: Request) -> HTTPResponse | ResponseStream | None:
        """Handle all A2A JSON-RPC requests.

        Routes by ``method`` name: v0.3 names use ``RequestHandler03``; native
        1.0 names parse ``params`` into protobuf and call the shared handler.
        Missing ``A2A-Version`` is treated as 0.3.
        """
        request_id: str | int | None = None
        try:
            if too_large := _payload_too_large_response(request):
                return too_large
            if auth_error := _validate_a2a_bearer_auth(request):
                return auth_error

            parse_error, body, request_id = _parse_json_body(request)
            if parse_error is not None:
                return parse_error

            structlogger.debug("a2a_server.sanic_app.handle_jsonrpc.body", body=body)
            try:
                base_request = JSONRPC20Request.from_data(body)
            except Exception as exc:
                return _jsonrpc_error_response(
                    request_id, InvalidRequestError(data=str(exc))
                )
            if not isinstance(base_request, JSONRPC20Request):
                return _jsonrpc_error_response(
                    request_id,
                    InvalidRequestError(message="Batch requests are not supported"),
                )
            if isinstance(body, dict) and body.get("jsonrpc") != "2.0":
                return _jsonrpc_error_response(
                    request_id,
                    InvalidRequestError(
                        message="Invalid request: 'jsonrpc' must be exactly '2.0'"
                    ),
                )

            method = base_request.method
            request_id = base_request._id
            if not method:
                return _jsonrpc_error_response(
                    request_id, InvalidRequestError(message="Method is required")
                )

            handler = _request_handler(request)
            call_context = _build_server_call_context(request)
            call_context.state["method"] = method
            call_context.state["request_id"] = request_id

            if method in _V03_METHOD_TO_MODEL:
                return await _handle_v03_method(
                    handler, method, body, call_context, request_id
                )
            return await _handle_native_method(
                handler, method, body, call_context, request_id
            )
        except A2AMessageInFlightConflict as exc:
            return _jsonrpc_in_flight_conflict_response(request_id, exc)
        except A2AError as exc:
            return _jsonrpc_error_response(request_id, exc)
        except Exception as exc:
            structlogger.exception(
                "a2a_server.sanic_app.handle_jsonrpc.unhandled_error",
                exception=str(exc),
            )
            return _jsonrpc_error_response(
                request_id, InternalError(message="Internal server error")
            )

    # ------------------------------------------------------------------ #
    # AgentCard endpoints                                                  #
    # ------------------------------------------------------------------ #

    @bp.get(constants.AGENT_CARD_WELL_KNOWN_PATH)
    async def serve_agent_card(request: Request) -> HTTPResponse:
        """Serve the AgentCard when bearer auth passes (if configured)."""
        return _serve_agent_card_if_authorized(request)

    @bp.get(PREV_AGENT_CARD_WELL_KNOWN_PATH)
    async def serve_agent_card_deprecated(request: Request) -> HTTPResponse:
        """Serve the AgentCard at the deprecated path when bearer auth passes."""
        structlogger.warning(
            "a2a_server.sanic_app.agent_card_deprecated_endpoint",
            deprecated_path=PREV_AGENT_CARD_WELL_KNOWN_PATH,
            preferred_path=constants.AGENT_CARD_WELL_KNOWN_PATH,
        )
        return _serve_agent_card_if_authorized(request)

    return bp


# ------------------------------------------------------------------ #
# Internal dispatch helpers                                            #
# ------------------------------------------------------------------ #


async def _handle_v03_method(
    handler: Any,
    method: str,
    body: Any,
    call_context: ServerCallContext,
    request_id: str | int | None,
) -> HTTPResponse | ResponseStream:
    """Validate, adapt, and dispatch one v0.3 JSON-RPC method."""
    _ensure_protocol_version(call_context, constants.PROTOCOL_VERSION_0_3)
    model_class = _V03_METHOD_TO_MODEL[method]
    try:
        specific_request = model_class.model_validate(body)
    except Exception as exc:
        return _jsonrpc_error_response(request_id, InvalidParamsError(data=str(exc)))
    v03_params = getattr(specific_request, "params", None)
    call_context.tenant = getattr(v03_params, "tenant", "") or ""

    adapter = RequestHandler03(request_handler=handler)
    if method in _V03_STREAMING_METHODS:
        stream = _v03_stream(adapter, specific_request, call_context)
        return await _sse_from_events(request_id, stream, call_context, compat=True)
    result = await _dispatch_v03(adapter, specific_request, call_context, request_id)
    return _jsonrpc_result_response(
        result.model_dump(mode="json", by_alias=True, exclude_none=True),
        _activated_extension_headers(call_context),
    )


async def _handle_native_method(
    handler: Any,
    method: str,
    body: Any,
    call_context: ServerCallContext,
    request_id: str | int | None,
) -> HTTPResponse | ResponseStream:
    """Parse params and dispatch one native 1.0 JSON-RPC method."""
    model_class = _NATIVE_METHOD_TO_MODEL.get(method)
    if model_class is None:
        return _jsonrpc_error_response(request_id, MethodNotFoundError())
    _ensure_protocol_version(call_context, constants.PROTOCOL_VERSION_1_0)
    try:
        params = body.get("params", {}) if isinstance(body, dict) else {}
        specific_request = ParseDict(params, model_class())
    except (ParseError, Exception) as exc:
        return _jsonrpc_error_response(request_id, InvalidParamsError(data=str(exc)))
    call_context.tenant = getattr(specific_request, "tenant", "") or ""

    if method in _NATIVE_STREAMING_METHODS:
        stream = _native_stream(handler, method, specific_request, call_context)
        return await _sse_from_events(request_id, stream, call_context, compat=False)
    result = await _dispatch_native(
        handler, method, specific_request, call_context, request_id
    )
    return _jsonrpc_result_response(
        _success_payload(request_id, result),
        _activated_extension_headers(call_context),
    )
